1	import { useState, useEffect, useRef } from "react";
2	import { useNavigate } from "@tanstack/react-router";
3	import { TOOLS } from "~/constants/tool";
4	import { BOOKS } from "~/constants/book";
5	import { askAI } from "~/server/ai.functions";
6	
7	type ResultItem = {
8	  type: "navigate" | "tool" | "book" | "ai-action";
9	  label: string;
10	  description: string;
11	  action: () => void;
12	  icon: string;
13	};
14	
15	type ChatMessage = {
16	  role: "user" | "assistant";
17	  content: string;
18	  actions?: Array<{ type: string; path?: string; url?: string; label?: string }>;
19	};
20	
21	function fuzzyMatch(query: string, target: string): number {
22	  const q = query.toLowerCase();
23	  const t = target.toLowerCase();
24	  if (t.includes(q)) return 100 + (q.length / t.length) * 50;
25	  const words = t.split(/\s+/);
26	  if (words.some((w) => w.startsWith(q))) return 80;
27	  let qi = 0;
28	  let score = 0;
29	  for (let ti = 0; ti < t.length && qi < q.length; ti++) {
30	    if (t[ti] === q[qi]) {
31	      score += 10;
32	      qi++;
33	    }
34	  }
35	  return qi === q.length ? score : 0;
36	}
37	
38	export const CommandAgent = () => {
39	  const [isOpen, setIsOpen] = useState(false);
40	  const [query, setQuery] = useState("");
41	  const [selectedIndex, setSelectedIndex] = useState(0);
42	  const [mode, setMode] = useState<"search" | "ai">("search");
43	  const [chatHistory, setChatHistory] = useState<ChatMessage[]>([]);
44	  const [isLoading, setIsLoading] = useState(false);
45	  const [cursorVisible, setCursorVisible] = useState(true);
46	  const inputRef = useRef<HTMLInputElement>(null);
47	  const resultsRef = useRef<HTMLDivElement>(null);
48	  const chatRef = useRef<HTMLDivElement>(null);
49	  const navigate = useNavigate();
50	
51	  // Cursor blink — only when modal is open
52	  useEffect(() => {
53	    if (!isOpen) return;
54	    const interval = setInterval(() => setCursorVisible((v) => !v), 530);
55	    return () => clearInterval(interval);
56	  }, [isOpen]);
57	
58	  // Keyboard shortcut and custom event to open
59	  useEffect(() => {
60	    const handleKeyDown = (e: KeyboardEvent) => {
61	      if ((e.metaKey || e.ctrlKey) && e.key === "k") {
62	        e.preventDefault();
63	        setIsOpen((prev) => !prev);
64	      }
65	      if (e.key === "Escape") {
66	        setIsOpen(false);
67	      }
68	    };
69	    const handleToggle = () => setIsOpen((prev) => !prev);
70	    window.addEventListener("keydown", handleKeyDown);
71	    window.addEventListener("toggle-command-agent", handleToggle);
72	    return () => {
73	      window.removeEventListener("keydown", handleKeyDown);
74	      window.removeEventListener("toggle-command-agent", handleToggle);
75	    };
76	  }, []);
77	
78	  // Focus input when opened
79	  useEffect(() => {
80	    if (isOpen) {
81	      setQuery("");
82	      setSelectedIndex(0);
83	      requestAnimationFrame(() => inputRef.current?.focus());
84	    } else {
85	      // Reset state when closed
86	      setMode("search");
87	      setChatHistory([]);
88	    }
89	  }, [isOpen]);
90	
91	  // Scroll chat to bottom
92	  useEffect(() => {
93	    if (chatRef.current) {
94	      chatRef.current.scrollTop = chatRef.current.scrollHeight;
95	    }
96	  }, [chatHistory]);
97	
98	  const close = () => {
99	    setIsOpen(false);
100	  };
101	
102	  const handleAction = async (action: {
103	    type: string;
104	    path?: string;
105	    url?: string;
106	    label?: string;
107	  }) => {
108	    if (action.type === "navigate" && action.path) {
109	      await navigate({ to: action.path });
110	      close();
111	    } else if (action.type === "open" && action.url) {
112	      window.open(action.url, "_blank", "noopener,noreferrer");
113	    }
114	  };
115	
116	  // Send AI query
117	  const chatHistoryRef = useRef(chatHistory);
118	  chatHistoryRef.current = chatHistory;
119	
120	  const sendAIQuery = async (userQuery: string) => {
121	    if (!userQuery.trim() || isLoading) return;
122	
123	    const currentHistory = chatHistoryRef.current;
124	    const newHistory: ChatMessage[] = [...currentHistory, { role: "user", content: userQuery }];
125	    setChatHistory(newHistory);
126	    setQuery("");
127	    setIsLoading(true);
128	
129	    try {
130	      const result = await askAI({
131	        data: {
132	          query: userQuery,
133	          history: newHistory.slice(-6).map((m) => ({
134	            role: m.role,
135	            content: m.content,
136	          })),
137	        },
138	      });
139	
140	      setChatHistory((prev) => [
141	        ...prev,
142	        {
143	          role: "assistant",
144	          content: result.response,
145	          actions: result.actions,
146	        },
147	      ]);
148	    } catch {
149	      setChatHistory((prev) => [
150	        ...prev,
151	        { role: "assistant", content: "Connection error. Try again." },
152	      ]);
153	    } finally {
154	      setIsLoading(false);
155	      requestAnimationFrame(() => inputRef.current?.focus());
156	    }
157	  };
158	
159	  // Build search index
160	  const allItems: ResultItem[] = (() => {
161	    const items: ResultItem[] = [];
162	
163	    const pages = [
164	      { path: "/", label: "HOME", desc: "Go to the landing page" },
165	      { path: "/blog", label: "BLOG", desc: "Browse all blog posts" },
166	      { path: "/reading-list", label: "READING LIST", desc: "Books and reading recommendations" },
167	      { path: "/tool", label: "TOOLS", desc: "Developer tools and utilities" },
168	    ];
169	    for (const page of pages) {
170	      items.push({
171	        type: "navigate",
172	        label: page.label,
173	        description: page.desc,
174	        icon: ">_",
175	        action: async () => {
176	          await navigate({ to: page.path });
177	          close();
178	        },
179	      });
180	    }
181	
182	    for (const tool of TOOLS) {
183	      items.push({
184	        type: "tool",
185	        label: tool.name,
186	        description: tool.description.slice(0, 120) + (tool.description.length > 120 ? "..." : ""),
187	        icon: "[]",
188	        action: () => {
189	          window.open(tool.link, "_blank", "noopener,noreferrer");
190	          close();
191	        },
192	      });
193	    }
194	
195	    for (const book of BOOKS) {
196	      items.push({
197	        type: "book",
198	        label: book.name,
199	        description: "From the reading list",
200	        icon: "{}",
201	        action: () => {
202	          window.open(book.link, "_blank", "noopener,noreferrer");
203	          close();
204	        },
205	      });
206	    }
207	
208	    return items;
209	  })();
210	
211	  // Filter and sort results
212	  const results = (() => {
213	    if (!query.trim()) {
214	      return allItems.filter((item) => item.type === "navigate");
215	    }
216	    return allItems
217	      .map((item) => ({
218	        item,
219	        score: Math.max(fuzzyMatch(query, item.label), fuzzyMatch(query, item.description) * 0.6),
220	      }))
221	      .filter(({ score }) => score > 0)
222	      .sort((a, b) => b.score - a.score)
223	      .slice(0, 12)
224	      .map(({ item }) => item);
225	  })();
226	
227	  // Auto-switch to AI mode when search has no results
228	  const autoSwitchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
229	
230	  useEffect(() => {
231	    if (autoSwitchTimerRef.current) {
232	      clearTimeout(autoSwitchTimerRef.current);
233	      autoSwitchTimerRef.current = null;
234	    }
235	
236	    if (mode === "search" && query.trim() && results.length === 0) {
237	      autoSwitchTimerRef.current = setTimeout(() => {
238	        setMode("ai");
239	      }, 200);
240	    }
241	
242	    return () => {
243	      if (autoSwitchTimerRef.current) {
244	        clearTimeout(autoSwitchTimerRef.current);
245	      }
246	    };
247	  }, [mode, query, results.length]);
248	
249	  useEffect(() => {
250	    setSelectedIndex(0);
251	  }, [results.length, query]);
252	
253	  useEffect(() => {
254	    if (resultsRef.current) {
255	      const selected = resultsRef.current.children[selectedIndex] as HTMLElement;
256	      selected?.scrollIntoView({ block: "nearest" });
257	    }
258	  }, [selectedIndex]);
259	
260	  const handleInputKeyDown = async (e: React.KeyboardEvent) => {
261	    // Tab to switch modes
262	    if (e.key === "Tab") {
263	      e.preventDefault();
264	      setMode((m) => (m === "search" ? "ai" : "search"));
265	      return;
266	    }
267	
268	    if (mode === "ai") {
269	      if (e.key === "Enter" && !e.shiftKey) {
270	        e.preventDefault();
271	        await sendAIQuery(query);
272	      }
273	      return;
274	    }
275	
276	    // Search mode keyboard nav
277	    if (e.key === "ArrowDown") {
278	      e.preventDefault();
279	      setSelectedIndex((i) => Math.min(i + 1, results.length - 1));
280	    } else if (e.key === "ArrowUp") {
281	      e.preventDefault();
282	      setSelectedIndex((i) => Math.max(i - 1, 0));
283	    } else if (e.key === "Enter" && results[selectedIndex]) {
284	      e.preventDefault();
285	      results[selectedIndex].action();
286	    }
287	  };
288	
289	  const typeLabels: Record<string, string> = {
290	    navigate: "NAV",
291	    tool: "TOOL",
292	    book: "BOOK",
293	    "ai-action": "AI",
294	  };
295	
296	  const typeColors: Record<string, string> = {
297	    navigate: "text-primary",
298	    tool: "text-secondary",
299	    book: "text-neon-yellow",
300	    "ai-action": "text-neon-green",
301	  };
302	
303	  if (!isOpen) return null;
304	
305	  return (
306	    <div className="fixed inset-0 z-200 flex items-start justify-center pt-[12vh]">
307	      {/* Backdrop */}
308	      <button
309	        type="button"
310	        className="absolute inset-0 bg-black/70 backdrop-blur-md"
311	        onClick={close}
312	        aria-label="Close command agent"
313	      />
314	
315	      {/* Modal */}
316	      <div className="relative w-full max-w-2xl mx-4 animate-scale-in">
317	        <div className="absolute -inset-px bg-linear-to-r from-primary/50 via-secondary/30 to-primary/50 opacity-60 blur-[1px]" />
318	
319	        <div className="relative bg-background border border-primary/20 overflow-hidden">
320	          {/* Header bar */}
321	          <div className="flex items-center gap-2 px-4 py-2 border-b border-primary/10 bg-surface/50">
322	            <span className="terminal-text text-xs text-primary/50">SYSTEM</span>
323	            <span className="terminal-text text-xs text-text-muted">//</span>
324	            <span className="terminal-text text-xs text-text-muted">COMMAND_AGENT v2.0</span>
325	            <div className="ml-auto flex items-center gap-3">
326	              {/* Mode toggle */}
327	              <div className="flex items-center border border-white/10">
328	                <button
329	                  type="button"
330	                  onClick={() => setMode("search")}
331	                  className={`terminal-text text-[10px] px-2 py-1 transition-all ${
332	                    mode === "search"
333	                      ? "bg-primary/20 text-primary"
334	                      : "text-text-muted hover:text-primary"
335	                  }`}
336	                >
337	                  SEARCH
338	                </button>
339	                <button
340	                  type="button"
341	                  onClick={() => setMode("ai")}
342	                  className={`terminal-text text-[10px] px-2 py-1 transition-all ${
343	                    mode === "ai"
344	                      ? "bg-neon-green/20 text-neon-green"
345	                      : "text-text-muted hover:text-neon-green"
346	                  }`}
347	                >
348	                  AI
349	                </button>
350	              </div>
351	              <span className="status-dot w-1.5! h-1.5!" />
352	            </div>
353	          </div>
354	
355	          {/* Content area */}
356	          {mode === "search" ? (
357	            /* Search results */
358	            <div ref={resultsRef} className="max-h-[50vh] overflow-y-auto">
359	              {results.length === 0 && query.trim() && (
360	                <div className="px-4 py-8 text-center">
361	                  <p className="terminal-text text-sm text-text-muted">NO_MATCH_FOUND</p>
362	                  <p className="terminal-text text-xs text-neon-green/60 mt-3 animate-pulse">
363	                    Switching to AI mode...
364	                  </p>
365	                </div>
366	              )}
367	
368	              {results.map((item, index) => (
369	                <button
370	                  type="button"
371	                  key={`${item.type}-${item.label}`}
372	                  className={`w-full flex items-center gap-3 px-4 py-3 text-left transition-all group ${
373	                    index === selectedIndex
374	                      ? "bg-primary/10 border-l-2 border-l-primary"
375	                      : "border-l-2 border-l-transparent hover:bg-surface-hover/50"
376	                  }`}
377	                  onClick={item.action}
378	                  onMouseEnter={() => setSelectedIndex(index)}
379	                >
380	                  <span
381	                    className={`terminal-text text-xs ${typeColors[item.type]} shrink-0 w-5 text-center opacity-70`}
382	                  >
383	                    {item.icon}
384	                  </span>
385	                  <div className="flex-1 min-w-0">
386	                    <div className="flex items-center gap-2">
387	                      <span
388	                        className={`terminal-text text-sm ${
389	                          index === selectedIndex ? "text-primary" : "text-text-main"
390	                        } transition-colors truncate`}
391	                      >
392	                        {item.label}
393	                      </span>
394	                      <span
395	                        className={`terminal-text text-[10px] ${typeColors[item.type]} opacity-60 shrink-0`}
396	                      >
397	                        [{typeLabels[item.type]}]
398	                      </span>
399	                    </div>
400	                    <p className="terminal-text text-xs text-text-muted/60 truncate mt-0.5">
401	                      {item.description}
402	                    </p>
403	                  </div>
404	                  <span
405	                    className={`terminal-text text-xs text-primary transition-opacity ${
406	                      index === selectedIndex ? "opacity-100" : "opacity-0"
407	                    }`}
408	                  >
409	                    &#x2192;
410	                  </span>
411	                </button>
412	              ))}
413	            </div>
414	          ) : (
415	            /* AI chat */
416	            <div ref={chatRef} className="max-h-[50vh] overflow-y-auto">
417	              {chatHistory.length === 0 && !isLoading && (
418	                <div className="px-4 py-6">
419	                  <p className="terminal-text text-xs text-text-muted/60 mb-4">
420	                    &gt; AI_AGENT_READY // Ask about tools, books, blog posts, or anything about
421	                    this site
422	                  </p>
423	                  <div className="flex flex-wrap gap-2">
424	                    {[
425	                      "What tools do you recommend for terminal?",
426	                      "Tell me about the blog posts",
427	                      "What books should I read as an engineer?",
428	                      "What is this site about?",
429	                    ].map((suggestion) => (
430	                      <button
431	                        key={suggestion}
432	                        type="button"
433	                        onClick={async () => {
434	                          setQuery(suggestion);
435	                          await sendAIQuery(suggestion);
436	                        }}
437	                        className="terminal-text text-[11px] text-text-muted px-3 py-1.5 border border-white/10 hover:border-neon-green/30 hover:text-neon-green hover:bg-neon-green/5 transition-all"
438	                      >
439	                        {suggestion}
440	                      </button>
441	                    ))}
442	                  </div>
443	                </div>
444	              )}
445	
446	              {chatHistory.map((msg, i) => (
447	                <div
448	                  key={i}
449	                  className={`px-4 py-3 ${msg.role === "user" ? "border-l-2 border-l-primary/30" : "border-l-2 border-l-neon-green/30 bg-surface/30"}`}
450	                >
451	                  <div className="flex items-center gap-2 mb-1">
452	                    <span
453	                      className={`terminal-text text-[10px] ${msg.role === "user" ? "text-primary" : "text-neon-green"}`}
454	                    >
455	                      {msg.role === "user" ? "YOU" : "AGENT"}
456	                    </span>
457	                  </div>
458	                  <p className="terminal-text text-sm text-text-main leading-relaxed">
459	                    {msg.content}
460	                  </p>
461	
462	                  {/* Action buttons from AI */}
463	                  {msg.actions && msg.actions.length > 0 && (
464	                    <div className="flex flex-wrap gap-2 mt-3">
465	                      {msg.actions.map((action, j) => (
466	                        <button
467	                          key={j}
468	                          type="button"
469	                          onClick={() => handleAction(action)}
470	                          className="terminal-text text-xs text-neon-green px-3 py-1.5 border border-neon-green/30 hover:bg-neon-green/10 hover:border-neon-green/60 transition-all flex items-center gap-2"
471	                        >
472	                          <span>{action.type === "navigate" ? ">_" : "[]"}</span>
473	                          <span>{action.label || action.path || action.url}</span>
474	                        </button>
475	                      ))}
476	                    </div>
477	                  )}
478	                </div>
479	              ))}
480	
481	              {isLoading && (
482	                <div className="px-4 py-3 border-l-2 border-l-neon-green/30 bg-surface/30">
483	                  <div className="flex items-center gap-2">
484	                    <span className="terminal-text text-[10px] text-neon-green">AGENT</span>
485	                  </div>
486	                  <p className="terminal-text text-sm text-text-muted animate-pulse mt-1">
487	                    Processing query...
488	                  </p>
489	                </div>
490	              )}
491	            </div>
492	          )}
493	
494	          {/* Input area */}
495	          <div className="flex items-center gap-3 px-4 py-4 border-t border-primary/10">
496	            <span
497	              className={`terminal-text text-sm shrink-0 ${mode === "ai" ? "text-neon-green" : "text-primary"}`}
498	            >
499	              {mode === "ai" ? (cursorVisible ? "?" : "\u00A0") : cursorVisible ? ">" : "\u00A0"}
500	            </span>
501	            <input
502	              ref={inputRef}
503	              type="text"
504	              value={query}
505	              onChange={(e) => setQuery(e.target.value)}
506	              onKeyDown={handleInputKeyDown}
507	              placeholder={
508	                mode === "ai" ? "Ask me anything about this site..." : "Type a command or search..."
509	              }
510	              className="flex-1 bg-transparent text-text-main terminal-text text-sm outline-none placeholder:text-text-muted/50"
511	              autoComplete="off"
512	              spellCheck={false}
513	            />
514	            {query && (
515	              <button
516	                type="button"
517	                onClick={() => setQuery("")}
518	                className="terminal-text text-xs text-text-muted hover:text-primary transition-colors"
519	              >
520	                CLEAR
521	              </button>
522	            )}
523	          </div>
524	
525	          {/* Footer */}
526	          <div className="flex items-center justify-between px-4 py-2 border-t border-primary/10 bg-surface/30">
527	            <div className="flex items-center gap-3">
528	              <span className="terminal-text text-[10px] text-text-muted/50">
529	                <kbd className="px-1 py-0.5 border border-white/10 bg-white/5">tab</kbd>{" "}
530	                {mode === "search" ? "AI mode" : "search"}
531	              </span>
532	              {mode === "search" ? (
533	                <>
534	                  <span className="terminal-text text-[10px] text-text-muted/50">
535	                    <kbd className="px-1 py-0.5 border border-white/10 bg-white/5">↑↓</kbd> navigate
536	                  </span>
537	                  <span className="terminal-text text-[10px] text-text-muted/50">
538	                    <kbd className="px-1 py-0.5 border border-white/10 bg-white/5">↵</kbd> select
539	                  </span>
540	                </>
541	              ) : (
542	                <span className="terminal-text text-[10px] text-text-muted/50">
543	                  <kbd className="px-1 py-0.5 border border-white/10 bg-white/5">↵</kbd> send
544	                </span>
545	              )}
546	              <span className="terminal-text text-[10px] text-text-muted/50">
547	                <kbd className="px-1 py-0.5 border border-white/10 bg-white/5">esc</kbd> close
548	              </span>
549	            </div>
550	            <span
551	              className={`terminal-text text-[10px] ${mode === "ai" ? "text-neon-green/40" : "text-text-muted/40"}`}
552	            >
553	              {mode === "ai"
554	                ? "llama-3.1"
555	                : `${results.length} result${results.length !== 1 ? "s" : ""}`}
556	            </span>
557	          </div>
558	        </div>
559	      </div>
560	    </div>
561	  );
562	};
