14	const markdownFiles = import.meta.glob("../blogs/*.md", {
15	  eager: true,
16	  query: "?raw",
17	  import: "default",
18	}) as Record<string, string>;
19	
20	function normalizeString(value: unknown): string | undefined {
21	  return typeof value === "string" && value.trim() ? value.trim() : undefined;
22	}
23	
24	function normalizeTags(value: unknown): string[] {
25	  if (!Array.isArray(value)) return [];
26	  return value
27	    .filter((tag): tag is string => typeof tag === "string")
28	    .map((tag) => tag.trim())
29	    .filter(Boolean);
30	}
31	
32	function parsePost(filePath: string, rawContent: string): BlogPost {
33	  const filename = filePath.split("/").pop() ?? filePath;
34	  const { frontMatter, html, preview } = parseMarkdownWithPreview(rawContent, 400);
35	
36	  const frontMatterTitle = normalizeString(frontMatter.title);
37	  const frontMatterSlug = normalizeString(frontMatter.slug);
38	  const description = normalizeString(frontMatter.description);
39	  const date = normalizeString(frontMatter.date);
40	
41	  const slug = frontMatterSlug || filename.replace(/\.md$/, "");
42	  const title = frontMatterTitle || slug;
43	
44	  return {
45	    filename,
46	    slug,
47	    title,
48	    html,
49	    preview: description ?? preview,
50	    description,
51	    date,
52	    tags: normalizeTags(frontMatter.tags),
