import { Outlet, createRootRoute, HeadContent, Scripts } from "@tanstack/react-router";
import { TanStackRouterDevtools } from "@tanstack/react-router-devtools";
import stylesheet from "../tailwind.css?url";
import { getRouter } from "../router";
import { Layout } from "../components/Layout/Layout";

declare module "@tanstack/react-router" {
  interface Register {
    router: ReturnType<typeof getRouter>;
  }
}

export const Route = createRootRoute({
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      {
        name: "viewport",
        content: "width=device-width, initial-scale=1",
      },
      { title: "Xiaofeng's Blog" },
      { name: "description", content: "Personal blog of Xiaofeng Xie - Software Engineer" },
    ],
    links: [
      { rel: "stylesheet", href: stylesheet },
      { rel: "preconnect", href: "https://fonts.googleapis.com" },
      { rel: "preconnect", href: "https://fonts.gstatic.com", crossOrigin: "anonymous" },
      {
        href: "https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap",
        rel: "stylesheet",
      },
    ],
  }),
  errorComponent: ErrorBoundary,
  component: RootLayout,
});

function ErrorBoundary({ error }: { error: unknown }) {
  // Log error to console in development
  if (process.env.NODE_ENV === "development") {
    console.error("ErrorBoundary caught an error:", error);
  }

  const getErrorMessage = (error: unknown): string => {
    if (error instanceof Error) {
      return error.message;
    }
    if (typeof error === "string") {
      return error;
    }
    return "An unexpected error occurred. Don't worry, it happens!";
  };

  const getErrorStack = (error: unknown): string | null => {
    if (error instanceof Error && process.env.NODE_ENV === "development") {
      return error.stack ?? null;
    }
    return null;
  };

  const errorMessage = getErrorMessage(error);
  const errorStack = getErrorStack(error);

  return (
    <html lang="en" className="h-full bg-background text-text-main">
      <head>
        <title>Oh no!</title>
        <HeadContent />
      </head>
      <body className="flex justify-center items-center min-h-screen">
        <div className="relative p-8 max-w-xl mx-4 text-center">
          <h1 className="text-3xl font-bold text-primary mb-6 max-w-full">
            Oops! Something went wrong...
          </h1>
          <p className="text-lg text-text-muted mb-6">{errorMessage}</p>

          {errorStack && (
            <details className="mb-6">
              <summary className="cursor-pointer text-text-main mb-2">Show Error Details</summary>
              <pre className="bg-surface p-4 rounded-lg text-sm text-text-muted overflow-x-auto max-h-32 border border-surface-hover animate-fade-in text-left">
                {errorStack}
              </pre>
            </details>
          )}

          <a
            href="/"
            className="inline-block bg-primary text-white text-sm font-semibold py-3 px-8 rounded-full shadow-lg transition-transform transform hover:scale-105 hover:shadow-xl animate-fade-in"
          >
            Take me Home
          </a>
        </div>
        <Scripts />
      </body>
    </html>
  );
}

function RootLayout() {
  return (
    <html lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        <Layout>
          <Outlet />
        </Layout>
        <Scripts />
        <TanStackRouterDevtools />
      </body>
    </html>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { TOOLS } from "~/constants/tool";

export const Route = createFileRoute("/tool")({
  component: Tool,
});

function Tool() {
  // Group tools by category
  const toolsByCategory = TOOLS.reduce(
    (acc, tool) => {
      if (!acc[tool.category]) {
        acc[tool.category] = [];
      }
      acc[tool.category].push(tool);
      return acc;
    },
    {} as Record<string, typeof TOOLS>,
  );

  const categories = Object.keys(toolsByCategory);

  return (
    <div className="relative max-w-7xl mx-auto px-6 py-12 animate-fade-in">
      {/* Header Section */}
      <div className="mb-16">
        {/* Breadcrumb */}
        <div className="flex items-center gap-2 mb-8 terminal-text text-sm text-text-muted">
          <Link to="/" className="hover:text-primary transition-colors">
            HOME
          </Link>
          <span className="text-accent">/</span>
          <span className="text-accent">TOOLS</span>
        </div>

        {/* Title */}
        <div className="relative inline-block">
          <div className="absolute -left-4 top-0 w-1 h-full bg-linear-to-b from-accent to-transparent" />
          <h1 className="text-4xl md:text-6xl font-bold">
            <span className="text-text-main">Arsenal</span>
            <span className="text-transparent bg-clip-text bg-linear-to-r from-accent to-primary">
              {" "}
              Matrix
            </span>
          </h1>
        </div>

        <p className="mt-6 text-lg text-text-muted max-w-2xl terminal-text">
          <span className="text-accent">&gt;</span> The software and hardware that powers the
          development workflow...
        </p>

        {/* Stats bar */}
        <div className="mt-8 flex flex-wrap items-center gap-6 p-4 border border-white/5 bg-surface/30 backdrop-blur-sm">
          <div className="flex items-center gap-2">
            <span className="w-2 h-2 bg-accent animate-pulse" />
            <span className="terminal-text text-xs text-text-muted">ARSENAL_LOADED</span>
          </div>
          <div className="h-4 w-px bg-white/10" />
          <div className="terminal-text text-xs text-text-muted">
            TOTAL_UNITS: <span className="text-accent">{TOOLS.length}</span>
          </div>
          <div className="h-4 w-px bg-white/10" />
          <div className="terminal-text text-xs text-text-muted">
            CATEGORIES: <span className="text-accent">{categories.length}</span>
          </div>
        </div>
      </div>

      {/* Tools Grid */}
      <div className="grid gap-6 md:grid-cols-2 lg:grid-cols-3">
        {TOOLS.map(({ description, icon, name, category, link }, index) => (
          <a
            key={name}
            href={link}
            target="_blank"
            rel="noopener noreferrer"
            className="group relative animate-slide-up"
            style={{ animationDelay: `${index * 0.03}s` }}
          >
            <div className="relative h-full cyber-card p-6 transition-all duration-500 hover:-translate-y-1 hover:border-accent/30">
              {/* Corner Accents */}
              <div className="absolute top-0 left-0 w-4 h-4 border-l border-t border-accent/30 group-hover:border-accent/60 group-hover:w-6 group-hover:h-6 transition-all duration-300" />
              <div className="absolute bottom-0 right-0 w-4 h-4 border-r border-b border-primary/30 group-hover:border-primary/60 group-hover:w-6 group-hover:h-6 transition-all duration-300" />

              {/* Header */}
              <div className="flex items-start justify-between mb-4">
                <div className="relative p-3 border border-white/10 group-hover:border-accent/30 group-hover:bg-accent/5 transition-all duration-300">
                  <img src={icon} alt={name} className="w-8 h-8" loading="lazy" decoding="async" />
                  {/* Pulse effect on hover */}
                  <div className="absolute inset-0 bg-accent/20 opacity-0 group-hover:opacity-100 group-hover:animate-pulse transition-opacity" />
                </div>

                <span className="terminal-text text-xs px-3 py-1.5 border border-white/10 bg-surface/50 text-text-muted group-hover:border-accent/30 group-hover:text-accent transition-all">
                  {category}
                </span>
              </div>

              {/* Content */}
              <h3 className="text-xl font-bold text-text-main mb-2 group-hover:text-accent transition-colors flex items-center gap-2">
                {name}
                <svg
                  className="w-4 h-4 opacity-0 group-hover:opacity-100 transform -translate-x-2 group-hover:translate-x-0 transition-all"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth={2}
                    d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14"
                  />
                </svg>
              </h3>

              <p className="text-text-muted text-sm leading-relaxed mb-4">{description}</p>

              {/* Footer */}
              <div className="flex items-center justify-between pt-4 border-t border-white/5">
                <span className="terminal-text text-xs text-text-muted">
                  [{String(index + 1).padStart(2, "0")}]
                </span>
                <span className="terminal-text text-xs text-accent opacity-0 group-hover:opacity-100 transition-opacity">
                  LAUNCH &gt;
                </span>
              </div>

              {/* Bottom Glow */}
              <div className="absolute bottom-0 left-0 w-0 h-0.5 bg-linear-to-r from-accent to-primary group-hover:w-full transition-all duration-500" />
            </div>
          </a>
        ))}
      </div>

      {/* Circuit Pattern Decoration */}
      <div className="fixed bottom-0 right-0 w-64 h-64 pointer-events-none opacity-10">
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <defs>
            <linearGradient id="circuit-grad" x1="0%" y1="0%" x2="100%" y2="100%">
              <stop offset="0%" stopColor="var(--color-accent)" />
              <stop offset="100%" stopColor="var(--color-primary)" />
            </linearGradient>
          </defs>
          <path
            d="M10 50 H30 V30 H50 M50 30 V10 M50 30 H70 V50 H90 M70 50 V70 H50 V90 M50 70 H30 V50"
            fill="none"
            stroke="url(#circuit-grad)"
            strokeWidth="0.5"
          />
          <circle cx="30" cy="50" r="2" fill="var(--color-accent)" />
          <circle cx="50" cy="30" r="2" fill="var(--color-primary)" />
          <circle cx="70" cy="50" r="2" fill="var(--color-accent)" />
          <circle cx="50" cy="70" r="2" fill="var(--color-primary)" />
        </svg>
      </div>
    </div>
  );
}

import { Link } from "@tanstack/react-router";
import { useState, useEffect } from "react";

export const Header = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);

  useEffect(() => {
    if (isMenuOpen) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "";
    }
    return () => {
      document.body.style.overflow = "";
    };
  }, [isMenuOpen]);

  const navLinks = [
    { to: "/", label: "HOME", code: "00" },
    { to: "/blog", label: "BLOG", code: "01" },
    { to: "/reading-list", label: "READING", code: "02" },
    { to: "/tool", label: "TOOLS", code: "03" },
  ];

  return (
    <header className="relative z-[110]">
      {/* Main Header Bar */}
      <div className="bg-background/80 backdrop-blur-xl border-b border-primary/10">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          {/* Logo */}
          <Link to="/" className="group flex items-center gap-3">
            <div className="relative">
              {/* Logo Icon */}
              <div className="w-10 h-10 border border-primary/50 flex items-center justify-center group-hover:border-primary transition-colors">
                <span className="terminal-text text-primary font-bold text-lg group-hover:glow-text-subtle transition-all">
                  X
                </span>
              </div>
              {/* Corner Accents */}
              <div className="absolute -top-1 -left-1 w-2 h-2 border-l-2 border-t-2 border-primary opacity-50 group-hover:opacity-100 transition-opacity" />
              <div className="absolute -bottom-1 -right-1 w-2 h-2 border-r-2 border-b-2 border-primary opacity-50 group-hover:opacity-100 transition-opacity" />
            </div>
            <div className="hidden sm:block">
              <span className="terminal-text text-lg font-bold text-text-main group-hover:text-primary transition-colors">
                XIAOFENG<span className="text-primary">.DEV</span>
              </span>
            </div>
          </Link>

          {/* Desktop Navigation */}
          <nav className="hidden md:flex items-center">
            <div className="flex items-center border border-white/5 bg-surface/30 backdrop-blur-sm">
              {navLinks.map((link) => (
                <Link
                  key={link.to}
                  to={link.to}
                  className="group relative px-6 py-3 flex items-center gap-2 text-sm font-medium text-text-muted hover:text-primary hover:bg-primary/5 transition-all border-r border-white/5 last:border-r-0"
                >
                  <span className="terminal-text text-xs text-primary/50 group-hover:text-primary transition-colors">
                    {link.code}
                  </span>
                  <span className="terminal-text tracking-wider">{link.label}</span>
                  {/* Active/Hover Indicator */}
                  <div className="absolute bottom-0 left-0 w-full h-0.5 bg-primary scale-x-0 group-hover:scale-x-100 transition-transform origin-left" />
                </Link>
              ))}
            </div>

            {/* Command Agent Trigger */}
            <button
              type="button"
              onClick={() => window.dispatchEvent(new CustomEvent("toggle-command-agent"))}
              className="ml-4 flex items-center gap-2 px-3 py-1.5 border border-primary/20 bg-primary/5 hover:border-primary/40 hover:bg-primary/10 transition-all group"
            >
              <span className="terminal-text text-xs text-text-muted group-hover:text-primary transition-colors">
                SEARCH
              </span>
              <kbd className="terminal-text text-[10px] text-text-muted/60 px-1.5 py-0.5 border border-white/10 bg-white/5">
                ⌘K
              </kbd>
            </button>

            {/* Status Indicator */}
            <div className="ml-4 flex items-center gap-2 px-3 py-1.5 border border-neon-green/30 bg-neon-green/5">
              <span className="status-dot" />
              <span className="terminal-text text-xs text-neon-green">ONLINE</span>
            </div>
          </nav>

          {/* Mobile Menu Button */}
          <button
            className="md:hidden relative w-12 h-12 flex items-center justify-center border border-white/10 hover:border-primary/50 hover:bg-primary/5 transition-all"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
            aria-label="Toggle menu"
          >
            <div className="flex flex-col gap-1.5 items-center justify-center">
              <span
                className={`w-5 h-0.5 bg-primary transition-all duration-300 ${isMenuOpen ? "rotate-45 translate-y-2" : ""}`}
              />
              <span
                className={`w-5 h-0.5 bg-primary transition-all duration-300 ${isMenuOpen ? "opacity-0" : ""}`}
              />
              <span
                className={`w-5 h-0.5 bg-primary transition-all duration-300 ${isMenuOpen ? "-rotate-45 -translate-y-2" : ""}`}
              />
            </div>
          </button>
        </div>
      </div>

      {/* Mobile Navigation - fixed overlay so it always appears above page content */}
      <div
        className={`md:hidden fixed inset-0 z-[120] transition-opacity duration-300 ${isMenuOpen ? "opacity-100 visible" : "opacity-0 invisible pointer-events-none"}`}
        aria-hidden={!isMenuOpen}
      >
        {/* Backdrop */}
        <button
          type="button"
          className="absolute inset-0 bg-black/60 backdrop-blur-sm"
          onClick={() => setIsMenuOpen(false)}
          aria-label="Close menu"
        />
        {/* Menu panel - below header bar (top-20 = 5rem) */}
        <div className="absolute top-20 left-0 right-0 z-10 bg-background border-b border-primary/10 shadow-xl">
          <nav className="max-w-7xl mx-auto px-6 py-6">
            <div className="space-y-2">
              {navLinks.map((link, index) => (
                <Link
                  key={link.to}
                  to={link.to}
                  className="group flex items-center gap-4 p-4 border border-white/5 hover:border-primary/30 hover:bg-primary/5 transition-all"
                  onClick={() => setIsMenuOpen(false)}
                  style={{ animationDelay: `${index * 0.05}s` }}
                >
                  <span className="terminal-text text-xs text-primary w-6">[{link.code}]</span>
                  <span className="terminal-text text-lg text-text-muted group-hover:text-primary transition-colors tracking-wider">
                    {link.label}
                  </span>
                  <svg
                    className="w-4 h-4 ml-auto text-primary opacity-0 group-hover:opacity-100 transform translate-x-0 group-hover:translate-x-1 transition-all"
                    fill="none"
                    stroke="currentColor"
                    viewBox="0 0 24 24"
                  >
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M9 5l7 7-7 7"
                    />
                  </svg>
                </Link>
              ))}
            </div>

            {/* Mobile Status */}
            <div className="mt-6 pt-6 border-t border-white/5 flex items-center justify-between">
              <div className="flex items-center gap-2">
                <span className="status-dot" />
                <span className="terminal-text text-xs text-neon-green">SYSTEM_ACTIVE</span>
              </div>
              <span className="terminal-text text-xs text-text-muted">v1.0.0</span>
            </div>
          </nav>
        </div>
      </div>
    </header>
  );
};

import GithubIcon from "../../assets/images/github.svg";
import LinkedinIcon from "../../assets/images/linkedin.svg";
import TwitterIcon from "../../assets/images/twitter.svg";

export const Footer = () => {
  return (
    <footer className="relative mt-auto border-t border-primary/10 bg-background/80 backdrop-blur-xl">
      {/* Top Line Accent */}
      <div className="absolute top-0 left-0 right-0 h-px bg-linear-to-r from-transparent via-primary/50 to-transparent" />

      <div className="max-w-7xl mx-auto px-6 py-8">
        {/* Main Footer Content */}
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          {/* Left - Copyright */}
          <div className="flex items-center gap-4">
            <div className="w-2 h-2 bg-neon-green animate-pulse" />
            <span className="terminal-text text-sm text-text-muted">
              <span className="text-primary">&copy; {new Date().getFullYear()}</span>{" "}
              <span className="text-text-main">XIAOFENG.DEV</span>{" "}
              <span className="text-text-muted">// ALL_RIGHTS_RESERVED</span>
            </span>
          </div>

          {/* Right - Social Links */}
          <div className="flex items-center gap-2">
            <span className="terminal-text text-xs text-text-muted mr-4">CONNECT &gt;</span>
            <div className="flex gap-1">
              <SocialLink
                href="https://github.com/XiaofengXie16"
                icon={GithubIcon}
                label="GitHub"
              />
              <SocialLink
                href="https://www.linkedin.com/in/xiaofengxie16/"
                icon={LinkedinIcon}
                label="LinkedIn"
              />
              <SocialLink
                href="https://twitter.com/XiaofengXie16"
                icon={TwitterIcon}
                label="Twitter"
              />
            </div>
          </div>
        </div>

        {/* Bottom Status Bar */}
        <div className="mt-6 pt-4 border-t border-white/5 flex flex-wrap items-center justify-center gap-6 terminal-text text-xs text-text-muted">
          <span>
            STATUS: <span className="text-neon-green">OPERATIONAL</span>
          </span>
          <span className="hidden sm:inline">|</span>
          <span>
            BUILT_WITH: <span className="text-primary">REACT</span> +{" "}
            <span className="text-secondary">TYPESCRIPT</span>
          </span>
          <span className="hidden sm:inline">|</span>
          <span>
            VERSION: <span className="text-accent">1.0.0</span>
          </span>
        </div>
      </div>
    </footer>
  );
};

const SocialLink = ({ href, icon, label }: { href: string; icon: string; label: string }) => (
  <a
    href={href}
    target="_blank"
    rel="noopener noreferrer"
    className="group relative p-3 border border-white/5 hover:border-primary/30 hover:bg-primary/5 transition-all duration-300"
    aria-label={label}
  >
    <img
      src={icon}
      className="w-5 h-5 opacity-50 group-hover:opacity-100 transition-all duration-300"
      alt={label}
      loading="lazy"
      decoding="async"
